CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, password_hash text NOT NULL, display_name text, email_verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_email_uq ON users(email);
CREATE TABLE sessions (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE password_resets (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose text NOT NULL CHECK (purpose IN ('reset','verify')), expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL, word_count integer NOT NULL CHECK(word_count >= 0), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX documents_owner_idx ON documents(user_id);
CREATE TABLE account_usage (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, words_used bigint NOT NULL DEFAULT 0 CHECK(words_used >= 0), word_allowance bigint NOT NULL CHECK(word_allowance >= 0), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(words_used <= word_allowance));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, event text NOT NULL, ip text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX audit_user_idx ON audit_events(user_id);
